254	    @Override
255	    @Transactional
256	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
257	        assertTelephoneIsUnique(owner);
258	        if (owner.isNew()) {
259	            assertCityHasCapacity(owner);
260	        }
261	        if (owner.isNew() && !sharesHousehold) {
262	            assertHouseholdIsUnique(owner);
263	        }
264	        if (owner.getRegistrationDate() == null) {
265	            owner.setRegistrationDate(LocalDate.now());
266	        }
267	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
268	        if (owner.isNew()) {
269	            assertDailyRegistrationLimit(owner);
270	        }
271	        if (owner.isNew() && owner.getCustomerCode() == null) {
272	            owner.setCustomerCode(generateCustomerCode(owner));
273	        }
274	        if (owner.isNew() && owner.getNamesakeCount() == null) {
275	            owner.setNamesakeCount(countNamesakes(owner));
276	        }
277	        ownerRepository.save(owner);
278	    }
279	
280	    /**
281	     * Count the existing owners that, at the moment this owner is created, share its first name
282	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
283	     * it never counts itself. This value is deterministic given the current data, so it is computed
284	     * once at creation time and stored.
285	     */
286	    private Integer countNamesakes(Owner owner) {
287	        String firstName = owner.getFirstName();
288	        String lastName = owner.getLastName();
289	        if (firstName == null || lastName == null) {
290	            return 0;
291	        }
292	        return (int) ownerRepository.findAll().stream()
293	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
294	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
295	                && lastName.equalsIgnoreCase(existing.getLastName()))
296	            .count();
297	    }
298	
299	    /**
300	     * Build an owner's {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where
301	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} the
302	     * upper-cased first three letters of the last name, and {@code NNNN} a per-city, 4-digit
303	     * zero-padded sequence equal to one more than the number of owners already in that city
304	     * (e.g. {@code 'LON-SMI-0007'}).
305	     */
306	    private String generateCustomerCode(Owner owner) {
307	        String city = owner.getCity();
308	        String city3 = codePrefix(city);
309	        String last3 = codePrefix(owner.getLastName());
310	        long sequence = ownerRepository.findAll().stream()
311	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
312	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
313	            .count() + 1L;
314	        return String.format("%s-%s-%04d", city3, last3, sequence);
315	    }
316	
317	    /**
318	     * Build a {@code customerCode} segment from {@code value}: its first three characters
319	     * (fewer if it is shorter), upper-cased.
320	     */
321	    private static String codePrefix(String value) {
322	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
323	    }
324	
325	    /**
326	     * Enforce that an owner's normalized telephone is not already used by any <em>other</em>
327	     * owner, throwing {@link DuplicateTelephoneException} if it is. The owner being saved is
328	     * excluded by id so updating an owner in place does not conflict with itself.
329	     */
330	    private void assertTelephoneIsUnique(Owner owner) {
331	        String normalized = Owner.normalizeTelephone(owner.getTelephone());
332	        if (normalized == null) {
333	            return;
334	        }
335	        boolean duplicate = ownerRepository.findAll().stream()
336	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
337	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
338	            .anyMatch(normalized::equals);
339	        if (duplicate) {
340	            throw new DuplicateTelephoneException(normalized);
341	        }
342	    }
343	
344	    /**
345	     * Enforce that no <em>other</em> owner already shares this owner's household, i.e. has the same
346	     * last name (compared case-insensitively with collapsed whitespace, see
347	     * {@link Owner#normalizeHousehold(String)}) and the same normalized address (see
348	     * {@link Owner#normalizeAddress(String)}), throwing {@link DuplicateHouseholdException} if one
349	     * does. The owner being saved is excluded by id. Callers skip this check when the request opted
350	     * in with {@code sharesHousehold}.
351	     */
352	    private void assertHouseholdIsUnique(Owner owner) {
353	        String lastName = Owner.normalizeHousehold(owner.getLastName());
354	        String address = Owner.normalizeAddress(owner.getAddress());
355	        if (lastName == null || address == null) {
356	            return;
357	        }
358	        boolean duplicate = ownerRepository.findAll().stream()
359	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
360	            .anyMatch(existing -> lastName.equals(Owner.normalizeHousehold(existing.getLastName()))
361	                && address.equals(Owner.normalizeAddress(existing.getAddress())));
362	        if (duplicate) {
363	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
364	        }
365	    }
366	
367	    /**
368	     * Enforce that the owner's city has not yet reached its capacity, throwing
369	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
370	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
371	     */
372	    private void assertCityHasCapacity(Owner owner) {
373	        String city = owner.getCity();
374	        if (city == null) {
375	            return;
376	        }
377	        long count = ownerRepository.findAll().stream()
378	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
379	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
380	            .count();
381	        if (count >= MAX_OWNERS_PER_CITY) {
382	            throw new CityAtCapacityException(city);
383	        }
384	    }
385	
386	    /**
387	     * Roll a registration date forward to the next business day. A date that falls on a Saturday or
388	     * Sunday is advanced to the following Monday; a weekday is returned unchanged. This is applied to
389	     * the effective registration date (whether supplied in the request or defaulted to the server
390	     * date) so that every value derived from it&mdash;such as the membership number's year segment
391	     * and the daily create-limit counting&mdash;uses the adjusted business day.
392	     */
393	    private static LocalDate rollToBusinessDay(LocalDate date) {
394	        if (date == null) {
395	            return null;
396	        }
397	        DayOfWeek dayOfWeek = date.getDayOfWeek();
398	        if (dayOfWeek == DayOfWeek.SATURDAY) {
399	            return date.plusDays(2);
400	        }
401	        if (dayOfWeek == DayOfWeek.SUNDAY) {
402	            return date.plusDays(1);
403	        }
404	        return date;
405	    }
406	
407	    /**
408	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
409	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
410	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
411	     * is excluded by id.
412	     */
413	    private void assertDailyRegistrationLimit(Owner owner) {
414	        LocalDate registrationDate = owner.getRegistrationDate();
415	        if (registrationDate == null) {
416	            return;
417	        }
418	        long count = ownerRepository.findAll().stream()
419	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
420	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
421	            .count();
422	        if (count >= MAX_OWNERS_PER_DAY) {
423	            throw new DailyRegistrationLimitException(registrationDate);
424	        }
425	    }
426	
427	    @Override
428	    @Transactional(readOnly = true)
429	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
430	        return ownerRepository.findByLastName(lastName);
431	    }
432	
433	    @Override
434	    @Transactional(readOnly = true)
435	    public Collection<Visit> findVisitsByPetId(int petId) {
436	        return visitRepository.findByPetId(petId);
437	    }
438	
439	    @Override
440	    @Transactional(readOnly = true)
441	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
442	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
443	    }
444	
445	    private <T> T findEntityById(Supplier<T> supplier) {
446	        try {
447	            return supplier.get();
448	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
449	            // Just ignore not found exceptions for Jdbc/Jpa realization
450	            return null;
451	        }
452	    }
453	
454	}
